<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\ValueObject\Holder\TenantLoginProviderCertificateAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantLoginProviderCertificateAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TenantLoginProviderCertificateAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getCertificate returns null on a freshly created holder.
     */
    public function testCertificateNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderCertificateAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isCertificateAssigned());
        $this->assertNull($holder->getCertificate());
    }
}
class ImplWithTenantLoginProviderCertificateAttributeHolderUnitTest
{
    use TenantLoginProviderCertificateAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedCertificateRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultCertificate();
    }
}
